},"explanation":{"correct":{"ko-KR":"그럼으로 이어 받고 전시회를 갈까요로 제안합니다.","zh-CN":"그럼承接调整，展览是不同活动，갈까요提出建议。"},"feedback":[{"ko-KR":"활동을 바꾸지 않는 문장을 빼세요.","zh-CN":"先排除没有改变活动的句子。"},{"ko-KR":"연결과 새 활동 제안이 모두 필요합니다.","zh-CN":"答案要有承接和新活动建议。"},{"ko-KR":"정답은 그럼 전시회에 갈까요?입니다.","zh-CN":"答案是그럼 전시회에 갈까요?。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":["영화가 정말 재미있네요!","네, 토요일 표가 있어요.","세 시에 만나요.","그럼 전시회에 갈까요?"],"node_code":"weekend-plan-talk","sort_order":2,"instruction":{"ko-KR":"다른 활동과 제안 질문을 모두 만족하는 문장을 고르세요.","zh-CN":"只选同时满足换活动和建议问句的一句。"},"activity_key":"dialogue-response","max_attempts":3,"activity_type":"single_choice","public_config":{"shuffle":true},"counts_toward_completion":true},{"prompt":{"ko-KR":"음성 초대를 듣고 서연과 준호가 어디에서 만나는지 고르세요.","zh-CN":"听语音邀约，判断서연想和준호在哪里见面。"},"secret":{"answer_key":{"kind":"index","value":1},"explanation":{"correct":{"ko-KR":"마지막 문장에서 극장 앞에서 만난다고 말합니다.","zh-CN":"原文最后一句明确说在剧场前见。"},"feedback":[{"ko-KR":"에서 만나요가 있는 문장을 다시 들으세요.","zh-CN":"再听带에서 만나요的句子。"},{"ko-KR":"장소는 마지막 문장의 세 시 반 앞에 있습니다.","zh-CN":"目标地点在最后一句、三点半之前。"},{"ko-KR":"정답은 극장 앞입니다.","zh-CN":"答案是극장 앞。"}],"privateListening":{"speaker":"F03／서연；第一人称语音留言","pauseMarks":"준호 씨, 이번 토요일에 같이 공연을 볼까요? ⏸ 오후 네 시 공연이에요. ⏸ 공연 후에 공원에서 걸을까요? ⏸ 극장 앞에서 세 시 반에 만나요.","slowScript":"준호 씨, 이번 토요일에 같이 공연을 볼까요? / 오후 네 시 공연이에요. / 공연 후에 공원에서 걸을까요? / 극장 앞에서 세 시 반에 만나요.","distractorReasons":{"0":"公园是演出后的活动地点，不是见面地点。","2":"独立听力没有美术馆。","3":"原文没有学校。"}}},"audio_status":"pending","transcript_ko":"준호 씨, 이번 토요일에 같이 공연을 볼까요? 오후 네 시 공연이에요. 공연 후에 공원에서 걸을까요? 극장 앞에서 세 시 반에 만나요.","audio_object_key":"korean-level-one/chapter-08/listening/chapter-08-listening-plan-place.mp3"},"options":["공원 입구","극장 앞","미술관 앞","학교 앞"],"node_code":"listen-and-invite","sort_order":1,"instruction":{"ko-KR":"보통 속도 두 번, 느린 속도 한 번 듣고 만나는 문장에 근거해 답하세요.","zh-CN":"正常语速最多两遍，慢速最多一遍；只依据音频见面句作答。"},"activity_key":"listening-plan-place","max_attempts":3,"activity_type":"listening","public_config":{"audioId":"chapter-08-listening-plan-place","shuffle":true,"audioStatus":"pending","slowReplayLimit":1,"normalReplayLimit":2},"counts_toward_completion":true},{"prompt":{"ko-KR":"대안을 포함해 두 역할로 40~55초, 8~10턴의 주말 약속 대화를 하세요.","zh-CN":"完成含备选方案的40—55秒、8—10轮双角色周末邀约。"},"secret":{"answer_key":{"kind":"open"},"explanation":{"correct":{"ko-KR":"녹음 정보와 여덟 점검을 정오나 점수 없이 저장했습니다.","zh-CN":"已保存录音元数据与八类自查；不产生正确性或分数。"},"feedback":[{"ko-KR":"두 역할, 8~10턴, 첫 계획과 대안을 확인하세요.","zh-CN":"先检查两个角色、8—10轮、第一方案和备选。"},{"ko-KR":"대상, 시간·장소, ㄷ 불규칙, -네요와 확인을 점검하세요.","zh-CN":"再检查对象、时间地点、ㄷ不规则、-네요和确认。"},{"ko-KR":"여덟 항목을 보완해 다시 녹음하며 발음 점수는 표시하지 않습니다.","zh-CN":"按八项清单补齐后重录；不显示虚假发音分数。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":[],"node_code":"listen-and-invite","sort_order":2,"instruction":{"ko-KR":"첫 제안, 응답·조정, 대안, 지시 대상, 시간·장소, ㄷ 불규칙, -네요와 마지막 확인을 넣으세요.","zh-CN":"加入第一建议、回应／调整、不同备选、指示对象、时间地点、ㄷ不规则建议、-네요新发现和最终确认。"},"activity_key":"speaking-invitation","max_attempts":3,"activity_type":"speaking","public_config":{"criteria":["第一项活动建议","接受或调整回应","不同备选活动","指示对象","具体时间地点","ㄷ不规则建议","-네요新发现","最终确认"],"turnLabel":{"ko-KR":"두 역할 교대 말차례 수","zh-CN":"双角色交替话轮数"},"maximumTurns":10,"minimumTurns":8,"maximumSeconds":55,"minimumSeconds":40,"requiredCriteria":8,"pronunciationScore":false,"enforceCompletionRequirements":true},"counts_toward_completion":true},{"prompt":{"ko-KR":"주말 약속 대화를 읽고 첫 계획, 바꾼 이유와 최종 시간·장소 세 문제에 답하세요.","zh-CN":"阅读周末约定聊天，完成第一方案、改变原因和最终时间地点三题。"},"secret":{"answer_key":{"kind":"index_array","value":[2,1,0]},"explanation":{"correct":{"ko-KR":"정답은 공연, 토요일 표 없음, 오후 두 시／미술관 앞입니다.","zh-CN":"答案依次是看演出、周六没票、下午两点／美术馆前。"},"feedback":[{"ko-KR":"첫 활동, 두 번째 사실과 마지막 시간·장소를 찾으세요.","zh-CN":"圈出第一句活动、第二句事实和最后两句时间地点。"},{"ko-KR":"다른 대화나 듣기 정보를 섞지 마세요.","zh-CN":"不要把主对话或听力信息带入。"},{"ko-KR":"대화를 근거로 세 문제를 다시 푸세요.","zh-CN":"依据聊天将三题全部正确重做。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":[],"node_code":"weekend-chat","sort_order":1,"instruction":{"ko-KR":"문제마다 하나를 고르고 공개된 대화에서 근거를 찾으세요.","zh-CN":"每题只选一个答案；全部依据公开聊天原句。"},"activity_key":"reading-weekend-chat","max_attempts":3,"activity_type":"single_choice","public_config":{"items":[{"id":"q1","options":["영화를 봐요","공원에서 걸어요","공연을 봐요","사진을 찍어요"],"question":"유나는 처음에 무엇을 제안했어요?"},{"id":"q2","options":["미술관이 멀어요","토요일 표가 없어요","시간이 없어요","공연이 재미없어요"],"question":"왜 계획을 바꿨어요?"},{"id":"q3","options":["오후 두 시／미술관 앞","오후 세 시／극장 앞","오후 네 시／공원 입구","오전 두 시／학교 앞"],"question":"두 사람은 언제 어디에서 만나요?"}],"reading":"[유나 님이 공연 포스터와 전시회 일정을 보냈습니다.]\n유나: 이번 토요일에 이 공연을 볼까요?\n준호: 좋은 생각이에요. 그런데 토요일 표가 없어요.\n유나: 그럼 이 전시회에 갈까요?\n준호: 좋아요. 방금 일정을 봤어요. 오후 두 시가 괜찮네요.\n유나: 네, 미술관 앞에서 만나요.","shuffle":true,"shuffleOptions":true},"counts_toward_completion":true},{"prompt":{"ko-KR":"친구에게 대안을 포함한 새로운 주말 약속 대화를 6~8턴으로 쓰세요.","zh-CN":"给同龄朋友写一段6—8轮、含备选方案的原创周末邀约聊天。"},"secret":{"answer_key":{"kind":"open"},"explanation":{"correct":{"ko-KR":"6~8턴, 여덟 정보와 자기 점검을 갖춘 대화를 정오나 점수 없이 저장했습니다.","zh-CN":"已保存满足6—8轮、八类信息与量规自查的原创聊天；不产生正确性或分数。"},"feedback":[{"ko-KR":"역할, 6~8턴, 첫 계획과 대안을 확인하세요.","zh-CN":"先数角色、6—8轮和第一方案与备选。"},{"ko-KR":"지시 대상, 시간·장소, ㄷ 불규칙과 -네요를 확인하세요.","zh-CN":"圈出指示对象、时间地点、ㄷ不规则和-네요。"},{"ko-KR":"틀로 빠진 부분을 보완하되 예시를 베끼지 마세요.","zh-CN":"按支架补齐缺项，但不要复制示范。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":[],"node_code":"weekend-chat","sort_order":2,"instruction":{"ko-KR":"여덟 정보를 쓰고 네 기준을 점검하세요. 예시를 베끼지 마세요.","zh-CN":"写八类信息并完成四维量规自查；不复制示范。"},"activity_key":"write-weekend-invitation","max_attempts":3,"activity_type":"writing","public_config":{"rubric":["信息完整","核心语法","回应逻辑与可理解度","格式与语气"],"maxSentences":8,"minSentences":6,"structureFrame":"이번 주말에 ___(으)ㄹ까요? → 좋아요.／미안해요. ___ → 그럼 ___(으)ㄹ까요? → 이/그/저 ___은/는 어때요? → ___시가 괜찮네요. → ___에서 만나요.","rubricConfirmation":"我已按四维量规完成自查","minimumPhraseGroups":5,"informationChecklist":["第一项活动建议","回应或调整理由","不同备选活动","指示对象","具体时间地点","ㄷ不规则建议","-네요新发现","最终确认"],"requiredPhraseGroups":[["볼까요","갈까요","걸을까요","들을까요","만날까요"],["이 ","그 ","저 "],["네요"],["걸을까요","들을까요"],["좋아요","미안해요","괜찮아요"]],"minimumHangulCharacters":50,"minimumInformationKinds":8,"requireCompletionChecklist":true},"counts_toward_completion":true},{"prompt":{"ko-KR":"형태가 맞고 괄호 안의 기능을 바르게 수행하는 문장을 모두 고르세요.","zh-CN":"选择所有形式正确且实现括号中功能的句子。"},"secret":{"answer_key":{"kind":"indices","value":[0,2,3,4]},"explanation":{"correct":{"ko-KR":"듣을까요를 제외한 네 문장이 맞고 듣다는 들을까요입니다.","zh-CN":"除듣을까요外其余四句形式与功能正确；듣다应为들을까요。"},"feedback":[{"ko-KR":"제안형, ㄷ 불규칙, 지시어 뒤 명사와 -네요 상황을 확인하세요.","zh-CN":"检查建议词尾、ㄷ不规则、指示词后的名词和-네요情境。"},{"ko-KR":"한 문장은 ㄷ을 그대로 두었습니다.","zh-CN":"有一句机械保留了ㄷ。"},{"ko-KR":"정답은 1, 3, 4, 5번입니다.","zh-CN":"正确项是第1、3、4、5句。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":["공원에서 걸을까요?（用걷다提议）","음악을 듣을까요?（用듣다提议）","영화가 재미있네요!（刚看完后的感叹）","저 전시회에 갈까요?（指远处对象并提议）","이 공연을 볼까요?（指明对象并提议）"],"node_code":"can-do-check","sort_order":1,"instruction":{"ko-KR":"맞는 표현을 모두 고르고 틀린 표현은 고르지 마세요.","zh-CN":"正确项全部选中且不多选才算完成。"},"activity_key":"review-multiple","max_attempts":3,"activity_type":"multiple_choice","public_config":{"shuffle":true,"selection":"multiple"},"counts_toward_completion":true},{"prompt":{"ko-KR":"실제 수행을 바탕으로 다섯 Can-do를 점검하고 다음 복습 위치를 정하세요.","zh-CN":"根据实际表现完成五项Can-do自查，并确定下一步复习位置。"},"secret":{"answer_key":{"kind":"open"},"explanation":{"correct":{"ko-KR":"다섯 점검과 복습 위치를 정오나 점수 없이 저장했으며 다른 증거를 대신하지 않습니다.","zh-CN":"五项自查与返回位置已保存；不替代客观题、录音或写作证据，也不产生分数。"},"feedback":[{"ko-KR":"제안, 대안, ㄷ 불규칙, 지시와 새 발견을 돌아보세요.","zh-CN":"逐项回想建议、备选、ㄷ不规则、对象指示和现场发现。"},{"ko-KR":"복습 필요를 구체적인 노드에 연결하세요.","zh-CN":"把需要复习对应到具体节点。"},{"ko-KR":"복습 항목이 있으면 none만 고를 수 없습니다.","zh-CN":"五项均须作答；有复习项时不能只选none。"}]},"audio_status":"pending","transcript_ko":null,"audio_object_key":null},"options":[],"node_code":"can-do-check","sort_order":2,"instruction":{"ko-KR":"다섯 항목에 답하고 복습이 필요하면 노드를, 모두 가능하면 none을 고르세요.","zh-CN":"五项都要回应；有复习项选至少一个返回节点，全部能完成时选择none。"},"activity_key":"self-check","max_attempts":3,"activity_type":"self_check","public_config":{"items":[{"id":"suggestion","label":"我能用-(으)ㄹ까요?提议活动和时间／-(으)ㄹ까요?로 활동과 시간을 제안할 수 있어요"},{"id":"irregular","label":"我能正确变化걷다和듣다／걷다와 듣다를 바르게 활용할 수 있어요"},{"id":"demonstrative","label":"我能用이／그／저+名词指对象／이／그／저 + 명사로 대상을 가리킬 수 있어요"},{"id":"discovery","label":"我能用-네요表达新发现／-네요로 새 발견을 말할 수 있어요"},{"id":"dialogue","label":"我能完成40—55秒、8—10轮邀约／40~55초, 8~10턴의 약속 대화를 할 수 있어요"}],"returnNodes":[{"label":"词汇","value":"activity-words"},{"label":"语法","value":"suggest-and-react"},{"label":"对话理解","value":"weekend-plan-talk"},{"label":"听说","value":"listen-and-invite"},{"label":"读写","value":"weekend-chat"},{"label":"无错／保持练习","value":"none"}],"requiredChecks":5},"counts_toward_completion":true}]}$chapter_seed$::jsonb;
  version_uuid uuid;
  lesson_uuid uuid;
  test_uuid uuid;
  chapter_uuid uuid;
  module_uuid uuid;
  node_uuid uuid;
  activity_uuid uuid;
  item jsonb;
begin
  select version.id into version_uuid
  from public.digital_textbook_versions version
  join public.digital_textbooks textbook on textbook.id=version.textbook_id
  where textbook.slug='korean-level-one-smart'
  order by version.version_number desc limit 1;
  if version_uuid is null then raise exception 'Cannot seed chapter 08: textbook version missing'; end if;

  select lesson.id into lesson_uuid
  from public.lessons lesson join public.courses course on course.id=lesson.course_id
  where course.slug='korean-beginner' and lesson.slug='basic-pronunciation' limit 1;
  if lesson_uuid is null then raise exception 'Cannot seed chapter 08: lesson missing'; end if;

  select id into test_uuid from public.chapter_tests where slug=seed#>>'{test,slug}' limit 1;
  if test_uuid is null then
    test_uuid := (seed#>>'{test,id}')::uuid;
    insert into public.chapter_tests (
      id,lesson_id,slug,course_key,chapter_number,title,korean_title,description,
      duration_minutes,passing_score,skills,version,status,student_app_id
    ) values (
      test_uuid,lesson_uuid,seed#>>'{test,slug}',seed#>>'{test,course_key}',
      (seed#>>'{test,chapter_number}')::integer,seed#>>'{test,title}',seed#>>'{test,korean_title}',
      seed#>>'{test,description}',(seed#>>'{test,duration_minutes}')::integer,
      (seed#>>'{test,passing_score}')::integer,seed#>'{test,skills}',
      (seed#>>'{test,version}')::integer,seed#>>'{test,status}',(seed#>>'{test,student_app_id}')::uuid
    );
  else
    update public.chapter_tests set
      lesson_id=lesson_uuid,course_key=seed#>>'{test,course_key}',
      chapter_number=(seed#>>'{test,chapter_number}')::integer,title=seed#>>'{test,title}',
      korean_title=seed#>>'{test,korean_title}',description=seed#>>'{test,description}',
      duration_minutes=(seed#>>'{test,duration_minutes}')::integer,
      passing_score=(seed#>>'{test,passing_score}')::integer,skills=seed#>'{test,skills}',
      version=(seed#>>'{test,version}')::integer,status=seed#>>'{test,status}',
      student_app_id=(seed#>>'{test,student_app_id}')::uuid,updated_at=now()
    where id=test_uuid;
  end if;

  delete from public.chapter_test_questions where test_id=test_uuid;
  for item in select value from jsonb_array_elements(seed->'questions') loop
    insert into public.chapter_test_questions (
      test_id,question_key,prompt,options,correct_option,explanation,skill,sort_order,
      question_type,default_points,difficulty,tags,status,version,is_chapter_test_item,
      ebook_section_step,ebook_page_reference
    ) values (
      test_uuid,item->>'question_key',item->>'prompt',item->'options',(item->>'correct_option')::integer,
      item->>'explanation',item->>'skill',(item->>'sort_order')::integer,item->>'question_type',
      (item->>'default_points')::numeric,item->>'difficulty',item->'tags',item->>'status',
      (item->>'version')::integer,(item->>'is_chapter_test_item')::boolean,
      item->>'ebook_section_step',item->>'ebook_page_reference'
    );
  end loop;

  select id into chapter_uuid from public.digital_textbook_chapters
  where version_id=version_uuid and chapter_number=(seed#>>'{chapter,chapter_number}')::integer limit 1;
  if chapter_uuid is null then
    chapter_uuid := (seed#>>'{chapter,id}')::uuid;
    insert into public.digital_textbook_chapters (
      id,version_id,chapter_test_id,slug,chapter_number,title,scenario,goal,status,
      production_status,editorial_status,native_review_status,audio_status,image_status,source_revision
    ) values (
      chapter_uuid,version_uuid,test_uuid,seed#>>'{chapter,slug}',(seed#>>'{chapter,chapter_number}')::integer,
      seed#>'{chapter,title}',seed#>'{chapter,scenario}',seed#>'{chapter,goal}',seed#>>'{chapter,status}',
      seed#>>'{chapter,production_status}',seed#>>'{chapter,editorial_status}',
      seed#>>'{chapter,native_review_status}',seed#>>'{chapter,audio_status}',
      seed#>>'{chapter,image_status}',seed#>>'{chapter,source_revision}'
    );
  else
    update public.digital_textbook_chapters set
      chapter_test_id=test_uuid,slug=seed#>>'{chapter,slug}',title=seed#>'{chapter,title}',
      scenario=seed#>'{chapter,scenario}',goal=seed#>'{chapter,goal}',status=seed#>>'{chapter,status}',
      production_status=seed#>>'{chapter,production_status}',editorial_status=seed#>>'{chapter,editorial_status}',
      native_review_status=seed#>>'{chapter,native_review_status}',audio_status=seed#>>'{chapter,audio_status}',
      image_status=seed#>>'{chapter,image_status}',source_revision=seed#>>'{chapter,source_revision}',updated_at=now()
    where id=chapter_uuid;
  end if;

  for item in select value from jsonb_array_elements(seed->'modules') loop
    insert into public.digital_textbook_modules (
      chapter_id,module_code,sort_order,accent_role,title,description
    ) values (
      chapter_uuid,item->>'module_code',(item->>'sort_order')::integer,item->>'accent_role',item->'title',item->'description'
    ) on conflict (chapter_id,module_code) do update set
      sort_order=excluded.sort_order,accent_role=excluded.accent_role,title=excluded.title,
      description=excluded.description,updated_at=now();
  end loop;

  for item in select value from jsonb_array_elements(seed->'nodes') loop
    select id into module_uuid from public.digital_textbook_modules
    where chapter_id=chapter_uuid and module_code=item->>'module_code';
    insert into public.digital_textbook_nodes (
      module_id,node_code,node_type,sort_order,estimated_minutes,title,content
    ) values (
      module_uuid,item->>'node_code',item->>'node_type',(item->>'sort_order')::integer,
      (item->>'estimated_minutes')::integer,item->'title',item->'content'
    ) on conflict (module_id,node_code) do update set
      node_type=excluded.node_type,sort_order=excluded.sort_order,
      estimated_minutes=excluded.estimated_minutes,title=excluded.title,
      content=excluded.content,updated_at=now();
  end loop;

  for item in select value from jsonb_array_elements(seed->'activities') loop
    select node.id into node_uuid from public.digital_textbook_nodes node
    join public.digital_textbook_modules module on module.id=node.module_id
    where module.chapter_id=chapter_uuid and node.node_code=item->>'node_code';
    insert into public.digital_textbook_activities (
      node_id,activity_key,activity_type,sort_order,prompt,instruction,options,
      public_config,max_attempts,counts_toward_completion
    ) values (
      node_uuid,item->>'activity_key',item->>'activity_type',(item->>'sort_order')::integer,
      item->'prompt',item->'instruction',item->'options',item->'public_config',
      (item->>'max_attempts')::integer,(item->>'counts_toward_completion')::boolean
    ) on conflict (node_id,activity_key) do update set
      activity_type=excluded.activity_type,sort_order=excluded.sort_order,prompt=excluded.prompt,
      instruction=excluded.instruction,options=excluded.options,public_config=excluded.public_config,
      max_attempts=excluded.max_attempts,counts_toward_completion=excluded.counts_toward_completion,
      updated_at=now()
    returning id into activity_uuid;
    insert into public.digital_textbook_activity_secrets (
      activity_id,answer_key,explanation,transcript_ko,audio_object_key,audio_status
    ) values (
      activity_uuid,item#>'{secret,answer_key}',item#>'{secret,explanation}',
      item#>>'{secret,transcript_ko}',item#>>'{secret,audio_object_key}',item#>>'{secret,audio_status}'
    ) on conflict (activity_id) do update set
      answer_key=excluded.answer_key,explanation=excluded.explanation,
      transcript_ko=excluded.transcript_ko,audio_object_key=excluded.audio_object_key,
      audio_status=excluded.audio_status,updated_at=now();
  end loop;

  delete from public.digital_textbook_activities activity
  using public.digital_textbook_nodes node,public.digital_textbook_modules module
  where activity.node_id=node.id and node.module_id=module.id and module.chapter_id=chapter_uuid
    and not exists (select 1 from jsonb_array_elements(seed->'activities') entry where entry->>'activity_key'=activity.activity_key);

  delete from public.digital_textbook_media_assets media
  using public.digital_textbook_nodes node,public.digital_textbook_modules module
  where media.node_id=node.id and node.module_id=module.id and module.chapter_id=chapter_uuid;
  for item in select value from jsonb_array_elements(seed->'media') loop
    select node.id into node_uuid from public.digital_textbook_nodes node
    join public.digital_textbook_modules module on module.id=node.module_id
    where module.chapter_id=chapter_uuid and node.node_code=item->>'node_code';
    activity_uuid := null;
    if item->>'activity_key' is not null then
      select id into activity_uuid from public.digital_textbook_activities
      where node_id=node_uuid and activity_key=item->>'activity_key';
    end if;
    insert into public.digital_textbook_media_assets (
      node_id,activity_id,asset_key,media_type,purpose,object_key,production_status,alt_text,metadata
    ) values (
      node_uuid,activity_uuid,item->>'asset_key',item->>'media_type',item->>'purpose',
      item->>'object_key',item->>'production_status',item->'alt_text',item->'metadata'
    );
  end loop;
end;
$chapter_08$;

